'ct_contentBox', 'a:2:{s:4:\"unit\";s:2:\"h2\";s:5:\"value\";s:13:\"Hamburger Hof\";}', '<p>Dank der Saalkapazitäten fanden in dem traditionsreichen Haus zahlreiche Großveranstaltungen statt. Tanzveranstaltungen, Messen und zahlreiche Feste ließen den &#34;Hamburger Hof&#34; zu einem beliebten Freizeitreff werden.</p>', 0, 0, NULL, '', '', '', '', 0, '', 'above', NULL, '', NULL, NULL, '', 0, 0, 0, 0, 0, 'ascending', '', '', '', '', NULL, '', '', '', '', '', '', 0, NULL, 0, 4, 0, 0, '', 0, '', '', NULL, '', '', NULL, '', 0, 300, 0, 0, 0, 0, 0, 0, 0, 0, NULL, 'a:2:{i:0;s:0:\"\";i:1;s:15:\"col-12 col-lg-3\";}', 0, '', '', '', 0, NULL, 0, NULL, NULL, '0', '0', '', '', 0, '', NULL, '', '', '', '', '', '', NULL, '', '', '', '', '', '', '', '', '', '', '', '', '', 'ce_cthemes_contentbox_bf', 'Mehr Informationen zum Hamburger Hof', 'Mehr dazu', '{{event_url::26|urlattr}}', '', '', '', '', NULL, 'sourceText', 0, NULL, 0, 'a:2:{s:5:\"value\";s:0:\"\";s:4:\"unit\";s:2:\"h2\";}', NULL, '', '', 0, 0, 0, 0, 'ascending', 0, 'com_default', NULL);
