, 'sliderElement', 'a:2:{s:4:\"unit\";s:2:\"h2\";s:5:\"value\";s:25:\"VEB Ziegelwerk Rotes Haus\";}', '<p>Die Ziegelei am Roten Haus war die letzte ihrer Art in Meißen, sie war nach fast 140 Jahren Produktion 1993 geschlossen worden.</p>', 1, 0, 0xc09740c7467611e9a91c408d5c22fa41, '', '', 'a:3:{i:0;s:0:\"\";i:1;s:0:\"\";i:2;s:2:\"24\";}', '', 0, '', 'above', NULL, '', NULL, NULL, '', 0, 0, 0, 0, 0, 'ascending', '', '', '', '', NULL, '', '', '', '', '', '', 0, NULL, 0, 4, 0, 0, '', 0, '', 'ce_slider_element_bf', NULL, '', '', NULL, '', 0, 300, 0, 0, 0, 0, 0, 0, 0, 0, NULL, 'a:2:{i:0;s:0:\"\";i:1;s:0:\"\";}', 0, '', '', '', 0, NULL, 0, NULL, NULL, '0', '0', '', '', 0, '', NULL, '', '', '', '', '', '', NULL, '', '', '', '', '', '', '', '', '', '', '', '', '', '', NULL, '', '', '', 'Industrie', 'Weiterlesen', '{{news_url::23|urlattr}}', NULL, 'sourceText', 0, NULL, 0, 'a:2:{s:5:\"value\";s:0:\"\";s:4:\"unit\";s:2:\"h2\";}', NULL, '', '', 0, 0, 0, 0, 'ascending', 0, 'com_default', 'Mehr Informationen zum VEB Ziegelwerk Rotes Haus');
