, 'ct_contentBox', 'a:2:{s:4:\"unit\";s:2:\"h2\";s:5:\"value\";s:9:\"Jahnhalle\";}', '<p>Die Turnhalle wurde 1893/95 im Auftrag des Turnvereins &#34;Frisch Auf&#34; errichtet. Anlässlich des 100. Todestags von &#34;Turnvater&#34; Jahn erhielt die Halle den offiziellen Namen Friedrich-Ludwig-Jahn-Turnhalle.</p>', 0, 0, NULL, '', '', '', '', 0, '', 'above', NULL, '', NULL, NULL, '', 0, 0, 0, 0, 0, 'ascending', '', '', '', '', NULL, '', '', '', '', '', '', 0, NULL, 0, 4, 0, 0, '', 0, '', '', NULL, '', '', NULL, '', 0, 300, 0, 0, 0, 0, 0, 0, 0, 0, NULL, 'a:2:{i:0;s:0:\"\";i:1;s:0:\"\";}', 0, '', '', '', 0, NULL, 0, NULL, NULL, '0', '0', '', '', 0, '', NULL, '', '', '', '', '', '', NULL, '', '', '', '', '', '', '', '', '', '', '', '', '', 'ce_cthemes_contentbox_bf', 'Mehr Informationen zur Jahnhalle', 'Mehr dazu', '{{event_url::27|urlattr}}', 'col-12 col-md-4', '', '', '', NULL, 'sourceText', 0, NULL, 0, 'a:2:{s:5:\"value\";s:0:\"\";s:4:\"unit\";s:2:\"h2\";}', NULL, '', '', 0, 0, 0, 0, 'ascending', 0, 'com_default', NULL);
