, 'ct_featureElement', 'a:2:{s:4:\"unit\";s:2:\"h3\";s:5:\"value\";s:13:\"Hamburger Hof\";}', '<p>Tanzveranstaltungen, Messen und zahlreiche Feste ließen den \"Hamburger Hof\" zu einem beliebten Freizeitreff werden.</p>', 0, 0, NULL, '', '', '', '', 0, '', 'above', NULL, '', NULL, NULL, '', 0, 0, 0, 0, 0, 'ascending', '', '', '', '', NULL, '', '', '', '', '', '', 0, NULL, 0, 4, 0, 0, '', 0, '', '', NULL, '', '', NULL, '', 0, 300, 0, 0, 0, 0, 0, 0, 0, 0, NULL, 'a:2:{i:0;s:0:\"\";i:1;s:0:\"\";}', 0, '', '', '', 0, NULL, 0, NULL, NULL, '0', '0', '', '', 0, '', NULL, '', '', '', '', '', '', NULL, '', '', '', '', '', '', '', '', '', '', '', '', 'fas fa-home', '', NULL, '', '', '', '', '', '', NULL, 'sourceText', 0, NULL, 0, 'a:2:{s:5:\"value\";s:0:\"\";s:4:\"unit\";s:2:\"h2\";}', NULL, '', '', 0, 0, 0, 0, 'ascending', 0, 'com_default', NULL);
