INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(28, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524413, 'Wir sind im IHK ecoFinder!\n\nDie pdir GmbH ist nun  ...', '', 0, 1637663134, 1637663134, '', '', NULL, '', '', 'Wir sind im IHK ecoFinder!<br><br>Die pdir GmbH ist nun offiziell eingetragen in Deutschlands größtem Umweltportal - dem IHK ecoFinder. In diesem findet man kompetente Anbieter von Produkten und Dienstleistungen aus der Umwelt- und Energiebranche - schnell, präzise und bundesweit. Wir haben uns zum Thema klimafreundliche Webseiten registrieren lassen 🌱💪<br><br>https://lnkd.in/ebG-aKpT<br><br>#ihk #ecofriendly #Klimakrise #klimafreundlich #webseite #digitalagentur #greenweb #greenwebdesign #sustainableweb #sustainablewebsite #sustainablewebdesign #klimafreundlichesinternet #klimafreundlichewebseite #pdir #01contaotheme', 0x03978afc541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6868857032938721280', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(29, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524413, 'Jaja - ab und zu wagen wir uns auch noch in die an ...', '', 0, 1636452825, 1636452825, '', '', NULL, '', '', 'Jaja - ab und zu wagen wir uns auch noch in die analoge Welt und erschaffen das ein oder andere Printprodukt. So richtig zum anfassen - wie die neuen Gutscheine der @diehafenmeister! Diese sind mit UV-Lack vereldelt sogar echt exklusiv geworden - eben passend zur Location ;)<br><br>Ach übrigens... Weihnachten steht ja bald vor der Tür und da wäre so ein Gutschein für ein außergewöhnliches Grill-Event bei den Hafenmeistern doch vielleicht ein tolles Geschenk?!?<br><br>Von uns jedenfalls wärmstens zu empfehlen! 🤩🤤🥳<br><br>👉 https://lnkd.in/eCyFS7nf<br><br>#printdesign #flyer #gutschein #eventlocation #dresden #weihnachtsgeschenk #grillevent', 0x03978af5541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6863780629511770112', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(30, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524414, 'Zum heutigen Weltinternettag mal ein paar Worte in ...', '', 0, 1635498294, 1635498294, '', '', NULL, '', '', 'Zum heutigen Weltinternettag mal ein paar Worte in Richtung Nachhaltigkeit: 🌱<br><br>Das Internet verbraucht Strom – und zwar eine Menge. Denn Rechenleistung, Kühlung und Stromversorgung von Tausenden von Servern kosten täglich Unmengen an Energie und verursachen einen enormen CO₂ Ausstoß. Wusstet ihr, dass eine durchschnittliche Webseite mit ca. 10.000 Seitenaufrufen im Monat um die 200 kg CO₂ pro Jahr verantwortet ?!?<br><br>Im gleichen Zeitraum bindet ein Baum im Schnitt ca. 11 Kg CO₂. Es müssten also ca. 20 Bäume gepflanzt werden, um das online CO₂ einer einzigen Website durch Bäume wieder zu kompensieren! Puh - das hört sich ziemlich viel an, oder?<br><br>Genau das haben wir uns auch gedacht und beschäftigten uns deshalb seit einiger Zeit mit der Erstellung klimafreundlicher Webseiten. Und wir haben festgestellt: Energieeffizientes Webdesign ist mehr als nur umweltfreundlich - es ist automatisch auch performanter, nutzerfreundlicher & SEO-optimierter! 💪<br><br>Wie das geht? Erklären wir dir hier:<br>https://lnkd.in/eRUPN27z<br><br>#weltinternettag #greenweb #greenwebdesign #sustainableweb #sustainablewebsite #sustainablewebdesign #klimafreundlichesinternet #klimafreundlichewebseite #webdesign #webdesignagency #webdevelopment #webdevelopmentagency #Klimakrise #klimakrise #pdir #01contaotheme', 0x03978aeb541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6859777036349702144', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(31, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524414, 'Tutorial-Video zum 0.1 Isotope Contao Theme verfüg ...', '', 0, 1626425582, 1626425582, '', '', NULL, '', '', 'Tutorial-Video zum 0.1 Isotope Contao Theme verfügbar!<br>Marvin erklärt euch, wie man mit der Contao Shop-Erweiterung Isotope und dem 0.1 Theme einen schicken Webshop erstellt. <br><br>Macht er echt gut, schaut mal rein!<br>Danke Marvin! <br><br>https://lnkd.in/eMs6CpE<br><br>#webshop #contaocms #contao #isotopeecommerce #contaowebsite #contaowebshop #onlineshop #ecommerce #pdir #01contaotheme', 0x03978ae4541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6821723323286790144', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(32, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524414, 'Neues Template für ausgefallene Online Shops!\nUnse ...', '', 0, 1624609850, 1624609850, '', '', NULL, '', '', 'Neues Template für ausgefallene Online Shops!<br>Unser \"schrägstes\" Contao Theme \"ODD\" kann nun auch Produkte präsentieren...<br><br>In der Shop-Version steht ein vorkonfigurierter Isotope eCommerce-Shop inkl. optimierter Startseite & typischer Shop-Elemente, wie Themenwelten, Marken und Produktslider im ausgefallenen ODD Style zur Verfügung.<br><br>Hier gehts zur DEMO:<br>https://lnkd.in/eCHGXR8<br><br>Hol dir das ODD Shop-Theme und viele weitere schicke Contao Themes hier:<br>https://contao-themes.net<br><br>#onlineshop #ecommerce #websitedesign #websitetemplate #webshop #shoptemplate #onlineshoptemplate<br>#contao #contaocms #isotopeecommerce #contaoisotope<br>#pdir #contaotheme #oddcontaotheme #odd', 0x03978adc541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6814107594328748032', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(33, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524415, 'Hey! Kennst du schon den pdir Newsletter?\nWas es d ...', '', 0, 1623773734, 1623773734, '', '', NULL, '', '', 'Hey! Kennst du schon den pdir Newsletter?<br>Was es da drin spannendes gibt und warum du den brauchen solltest fragst du dich?<br><br>* Du bekommst alle unsere Freebies (nützliche Checklisten, gratis E-Books, ...) als aller erstes<br>* Du erhältst stets aktuelle Updates zu Themes und Extensions<br>* Du wirst stets mit wertvollen Tipps, Tricks und unseren Learnings zum Thema Web-Entwicklung und Contao versorgt<br>* Du bekommst einen Einblick in unseren Agenturalltag und die ein oder andere Anekdote zu lesen<br>* Manchmal versenden wir auch Hundebaby-Bilder <br> aber nur selten...<br><br>Klingt gut? Dann meld dich hier kostenlos und unverbindlich zum pdir Newsletter an:<br><br>https://pdir.de/newsletter<br><br>Kein Spam, niemals. Versprochen.<br><br>#newsletter #contao #webentwicklung #webdevelopment #websitetheme #websitetemplates #pdir #tippsundtricks #webagenturalltag #bürohund', 0x03978ad4541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6810600668986974208', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(34, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524415, 'Online-Shop-Entwickler aufgepasst:\nWir haben dem 0 ...', '', 0, 1622715433, 1622715433, '', '', NULL, '', '', 'Online-Shop-Entwickler aufgepasst:<br>Wir haben dem 0.1 Isoptope Bundle eine schicke Shop-Startseite spendiert - mit vorkonfigurierten Shop-Elementen, wie Themenwelten, Markenlogos und Produktslider im klimafreundlichen 0.1 Stil:<br><br>https://lnkd.in/ehSiNUp<br><br>Einen schicken, performanten Online-Shop mit Contao aufsetzen? Sollte also kein Problem mehr sein - los gehts!<br><br>Das Theme ist auch in der Shopversion (mit 0.46g C02) übrigens immernoch klimafreundlich <br><br>#onlineshop #ecommerce #websitedesign #websitetemplate #webshop #shoptemplate<br>#contao #contaocms #isotopeecommerce #contaoisotope<br>#pdir #contaotheme #01contaotheme #greenweb #Klimakrise #saveenergy #sustainableweb #sustainablewebdesign', 0x03978ac8541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6806161831955111936', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(35, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524420, '3 Jahre DSGVO 😱 und was haben wir daraus gelernt?! ...', '', 0, 1621949572, 1621949572, '', '', NULL, '', '', '3 Jahre DSGVO 😱 und was haben wir daraus gelernt?!<br><br>Regeln zum Datenschutz gab es auch bereits zu genüge vor Einführung der DSGVO im Mai 2018, aber in diesem Zuge bekam das Thema Datenschutz in Deutschland nochmal eine ganz andere Aufmerksamkeit und es herrschte fortan viel Unsicherheit und Verwirrung. Im Nachhinein lässt sich sagen, dass die ganze Aufregung wohl etwas übertrieben war, die Abmahnwellen bleiben aus, Klarheit über die nun geltenden Regeln allerdings ebenfalls, denn viele sind immer noch schwammig und werden von verschiedenen Experten unterschiedlich ausgelegt.<br><br>Was wir davon halten, daraus gelernt haben und uns die Erfahrung gezeigt hat, haben wir dir mal in einem Blogbeitrag festgehalten: <br><br>👉 https://lnkd.in/dvsWhzp<br><br>#DSGVO #datenschutz #datenschutzrecht #pdir #checkliste #freebie', 0x03978a95541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6802949578397118464', '', '', '');
INSERT INTO `tl_news` (`id`, `featured`, `addImage`, `overwriteMeta`, `fullsize`, `addEnclosure`, `target`, `published`, `noComments`, `pid`, `tstamp`, `headline`, `alias`, `author`, `date`, `time`, `pageTitle`, `robots`, `description`, `canonicalLink`, `subheadline`, `teaser`, `singleSRC`, `alt`, `imageTitle`, `size`, `imageUrl`, `caption`, `floating`, `enclosure`, `source`, `linkText`, `jumpTo`, `articleId`, `url`, `cssClass`, `start`, `stop`) VALUES(36, 0, 1, 0, 0, 0, 1, 1, 0, 3, 1638524420, 'Vom GEBEN und NEHMEN\n\nEs ist nicht immer einfach a ...', '', 0, 1621348850, 1621348850, '', '', NULL, '', '', 'Vom GEBEN und NEHMEN<br><br>Es ist nicht immer einfach als Webentwickler & Dienstleister neben der Entwicklungsarbeit guten Support für die eigenen Produkte zu liefern - aber wir geben stets unser Bestes... und freuen uns wie Schnitzel, wenn unsere Kunden es uns danken.<br>Deshalb heute ein DANKE an alle Kunden zurück, die uns in letzter Zeit so fleißg positiv bei Google Business bewertet haben!!! <br><br>Wenn auch du in dieser Liste erscheinen willt, lass uns gern eine Bewertung da ;)<br> > https://lnkd.in/eaVbArw<br>Danke!<br><br>#googlerezension #testimonial #businessbewertung #kundenfeedback', 0x08043c64541d11ec8ee0e0d55e59bff3, '', '', '', '', '', 'above', NULL, 'external', '', 0, 0, 'https://www.linkedin.com/feed/update/urn:li:activity:6800429967768391681', '', '', '');
INSERT INTO `tl_newsletter` (`id`, `addFile`, `sendText`, `externalImages`, `sent`, `pid`, `tstamp`, `subject`, `alias`, `preheader`, `content`, `text`, `files`, `template`, `mailerTransport`, `sender`, `senderName`, `date`) VALUES(4, 0, 0, 0, 1, 4, 1511793022, 'Keeping everyone up to date', '', '', '<p><b>Keeping everyone up to date</b></p>\n<p>Contao has a built in Newsletter administration system. It offers some features to create newsletters on a regular basis. Your are able to set up an HTML template, create your newsletters just as plain text or use both functionalities. Even attachments or external images can optionally be integrated.<b><br><br></b>SATURDAY<br>December 24<sup>th</sup>, 2013<br>7:30 pm</p>\n<p>SUNDAY<br>December 26<sup>th</sup>, 2013<br>3:00 pm</p>\n<p><b>Tickets $20[nbsp]to[nbsp]$40</b></p>\n<p>Call (416) 872-4255</p>', '', 0x613a313a7b693a303b4e3b7d, 'mail_default', '', '', '', '1511949450');
INSERT INTO `tl_newsletter` (`id`, `addFile`, `sendText`, `externalImages`, `sent`, `pid`, `tstamp`, `subject`, `alias`, `preheader`, `content`, `text`, `files`, `template`, `mailerTransport`, `sender`, `senderName`, `date`) VALUES(5, 0, 0, 0, 0, 4, 1511948990, 'The right newsletter for everyone', 'the-right-newsletter-for-everyone', '', '<p><b>The right newsletter for everyone</b></p>\n<p>The newsletter functionalities of Contao allows you to create different \"Channels\". So it\'s possible to adress visitors or regular users of your site with their specific interests. Before you send a newsletter to a list of subscribers you can make the use of the option to send a preview. Better check your newsletters on all mail clients. Some of you might know that a lot of mail servers just allow a certain amount of Emails sent within a time-amount: The \"Mails per cycle\" function will help here with larger lists.<b><br><br></b>SATURDAY<br>December 24<sup>th</sup>, 2013<br>7:30 pm</p>\n<p>SUNDAY<br>December 26<sup>th</sup>, 2013<br>3:00 pm</p>\n<p><b>Tickets $20[nbsp]to[nbsp]$40</b></p>\n<p>Call (416) 872-4255</p>', 'TEXT Content', 0x613a313a7b693a303b4e3b7d, 'mail_default', '', '', '', '1360273849');
